CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('SUPER_ADMIN','SECTOR_ADMIN','MANAGEMENT') NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,last_login_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS sectors(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_sectors(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,sector_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,sector_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(sector_id) REFERENCES sectors(id));
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions(id INT AUTO_INCREMENT PRIMARY KEY,sector_id INT NOT NULL,category_id INT NOT NULL,title VARCHAR(300) NOT NULL,description TEXT,type ENUM('rating_5','nps_10','boolean','multiple_choice','text') NOT NULL,display_order INT NOT NULL DEFAULT 0,required BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,options_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(sector_id) REFERENCES sectors(id),FOREIGN KEY(category_id) REFERENCES categories(id),INDEX(sector_id,active));
CREATE TABLE IF NOT EXISTS question_options(id INT AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,label VARCHAR(255) NOT NULL,value VARCHAR(120) NOT NULL,display_order INT NOT NULL DEFAULT 0,UNIQUE(question_id,value),FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE IF NOT EXISTS surveys(id BIGINT AUTO_INCREMENT PRIMARY KEY,sector_id INT NOT NULL,attendance_date DATE NOT NULL,attendance_shift ENUM('morning','afternoon','night') NOT NULL,nps_score TINYINT NOT NULL,status VARCHAR(20) DEFAULT 'submitted',is_demo BOOLEAN NOT NULL DEFAULT FALSE,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(sector_id) REFERENCES sectors(id),INDEX(sector_id,attendance_date),INDEX(is_demo));
CREATE TABLE IF NOT EXISTS survey_answers(id BIGINT AUTO_INCREMENT PRIMARY KEY,survey_id BIGINT NOT NULL,question_id INT NOT NULL,answer_value TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(survey_id,question_id),FOREIGN KEY(survey_id) REFERENCES surveys(id),FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT NULL,details JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
